begin read only;set local statement_timeout='30s';
do $actor$ declare actor uuid;begin select id into actor from public.profiles where role='admin' and status='active' order by created_at limit 1;perform set_config('request.jwt.claim.sub',actor::text,true);end $actor$;
set local role authenticated;
do $measure$ declare plan_id uuid; started timestamptz; result jsonb; overview jsonb; samples jsonb:='[]';sample integer;begin
select id into plan_id from public.health_plans where public.network_normalize(name) like '%unicasf%' order by id limit 1;
overview:=public.health_plan_overview(plan_id);
for sample in 1..3 loop started:=clock_timestamp();result:=public.browse_network('{"category":"health_plans"}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','plan_list','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.health_plan_overview(plan_id);samples:=samples||jsonb_build_array(jsonb_build_object('operation','overview','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.health_plan_network(plan_id,'establishments','{"sort":"name"}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','establishments','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.health_plan_network(plan_id,'doctors','{"sort":"name"}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','doctors','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.health_plan_network(plan_id,'specialties','{}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','specialties','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.health_plan_network(plan_id,'doctors','{"city":"Belém","q":"cardiologia"}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','filtered_doctors','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.network_lookup('doctors','',null,true);samples:=samples||jsonb_build_array(jsonb_build_object('operation','lookup','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
for sample in 1..3 loop started:=clock_timestamp();result:=public.browse_network('{}',1,12);samples:=samples||jsonb_build_array(jsonb_build_object('operation','directory','sample',sample,'database_ms',round((extract(epoch from clock_timestamp()-started)*1000)::numeric,2),'response_bytes',octet_length(result::text),'total',result->'total','items',jsonb_array_length(coalesce(result->'items','[]'))));end loop;
perform set_config('minha_saude.explorer',jsonb_build_object('measurements',samples,'counts',jsonb_build_object('establishments',overview->'establishments_count','doctors',overview->'doctors_count','specialties',overview->'specialties_count','cities',overview->'cities_count'),'summary_has_provider_arrays',overview?'establishments' or overview?'doctors')::text,true);end $measure$;
select current_setting('minha_saude.explorer')::jsonb report;rollback;